-- Modelo inicial para Microsoft SQL Server. Revisar por migrações antes de produção.
CREATE TABLE customers (id BIGINT IDENTITY PRIMARY KEY, email NVARCHAR(254) NOT NULL UNIQUE, display_name NVARCHAR(120) NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'customer' CHECK (role IN ('owner','admin','support','editor','customer')), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE products (id BIGINT IDENTITY PRIMARY KEY, name NVARCHAR(150) NOT NULL, category VARCHAR(30) NOT NULL, price DECIMAL(12,2) NULL CHECK (price >= 0), currency CHAR(3) NOT NULL DEFAULT 'BRL', visible BIT NOT NULL DEFAULT 0, description NVARCHAR(MAX), updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE orders (id BIGINT IDENTITY PRIMARY KEY, customer_id BIGINT NOT NULL REFERENCES customers(id), status VARCHAR(20) NOT NULL DEFAULT 'pending', total DECIMAL(12,2) NOT NULL CHECK(total >= 0), currency CHAR(3) NOT NULL DEFAULT 'BRL', provider_reference VARCHAR(150) NULL UNIQUE, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE order_items (id BIGINT IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id), product_id BIGINT NOT NULL REFERENCES products(id), product_name NVARCHAR(150) NOT NULL, unit_price DECIMAL(12,2) NOT NULL CHECK(unit_price >= 0), quantity INT NOT NULL DEFAULT 1 CHECK(quantity > 0));
CREATE TABLE licenses (id BIGINT IDENTITY PRIMARY KEY, customer_id BIGINT NOT NULL REFERENCES customers(id), product_id BIGINT NOT NULL REFERENCES products(id), order_item_id BIGINT NULL REFERENCES order_items(id), key_hash CHAR(64) NOT NULL UNIQUE, domain VARCHAR(253) NOT NULL, domain_verified_at DATETIME2 NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', expires_at DATETIME2 NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE license_events (id BIGINT IDENTITY PRIMARY KEY, license_id BIGINT NOT NULL REFERENCES licenses(id), actor_id BIGINT NULL REFERENCES customers(id), event_type VARCHAR(40) NOT NULL, metadata NVARCHAR(MAX), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE tickets (id BIGINT IDENTITY PRIMARY KEY, customer_id BIGINT NOT NULL REFERENCES customers(id), license_id BIGINT NULL REFERENCES licenses(id), assigned_to BIGINT NULL REFERENCES customers(id), subject NVARCHAR(200) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'open', priority VARCHAR(20) NOT NULL DEFAULT 'normal', created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE ticket_messages (id BIGINT IDENTITY PRIMARY KEY, ticket_id BIGINT NOT NULL REFERENCES tickets(id), author_id BIGINT NOT NULL REFERENCES customers(id), body NVARCHAR(MAX) NOT NULL, internal_note BIT NOT NULL DEFAULT 0, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE attachments (id BIGINT IDENTITY PRIMARY KEY, message_id BIGINT NOT NULL REFERENCES ticket_messages(id), storage_key VARCHAR(255) NOT NULL UNIQUE, original_name NVARCHAR(255) NOT NULL, content_type VARCHAR(100) NOT NULL, byte_size BIGINT NOT NULL, sha256 CHAR(64) NOT NULL);
CREATE TABLE content_entries (id BIGINT IDENTITY PRIMARY KEY, kind VARCHAR(20) NOT NULL CHECK(kind IN ('news','project','testimonial','demo')), title NVARCHAR(200) NOT NULL, slug VARCHAR(200) NOT NULL UNIQUE, body NVARCHAR(MAX), metadata NVARCHAR(MAX) CHECK(ISJSON(metadata)=1 OR metadata IS NULL), status VARCHAR(20) NOT NULL DEFAULT 'draft', sort_order INT NOT NULL DEFAULT 0, author_id BIGINT NOT NULL REFERENCES customers(id), published_at DATETIME2 NULL, updated_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE content_revisions (id BIGINT IDENTITY PRIMARY KEY, entry_id BIGINT NOT NULL REFERENCES content_entries(id), snapshot NVARCHAR(MAX) NOT NULL CHECK(ISJSON(snapshot)=1), actor_id BIGINT NOT NULL REFERENCES customers(id), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE audit_events (id BIGINT IDENTITY PRIMARY KEY, actor_id BIGINT NULL REFERENCES customers(id), action VARCHAR(80) NOT NULL, resource_type VARCHAR(40) NOT NULL, resource_id BIGINT NULL, metadata NVARCHAR(MAX), created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE webhook_events (id BIGINT IDENTITY PRIMARY KEY, provider VARCHAR(40) NOT NULL, external_id VARCHAR(150) NOT NULL, processed_at DATETIME2 NULL, created_at DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(), CONSTRAINT uq_webhook UNIQUE(provider,external_id));
CREATE INDEX ix_licenses_customer ON licenses(customer_id,status);
CREATE INDEX ix_tickets_customer ON tickets(customer_id,status);
CREATE INDEX ix_content_public ON content_entries(kind,status,published_at);
